import { test, expect } from '@playwright/test';

test('signup-happy', async ({ page }) => {
  await page.goto('/signup');
  await expect(page.getByText('Bem-vindo')).toBeVisible();
  await page.getByRole('button', { name: 'Começar' }).click();
  await page.goto('/dashboard');
  await expect(page.locator('[data-testid=activation-complete]')).toBeVisible();
  await page.screenshot({ path: 'artifacts/signup-happy.png', fullPage: true });
  // evidencia do cenário signup-happy: trace + screenshot
});

